#pragma once
//------------------------------------------------------------------------------
// il2cpp_string_normalize.h -- System.String Unicode normalization icalls
// (the Normalize / IsNormalized surface, stringnormalize.cpp).
//
// .NET Framework 4.8 implements String.Normalize / IsNormalized on Windows
// through the NLS (National Language Support) normalization tables. This
// runtime carries an INDEPENDENT implementation of UAX #15 (Unicode
// Normalization Forms) built from the complete, versioned UnicodeData tables
// generated by scripts/gen_unicode_norm.py (see
// il2cpp_unicode_norm_data.h / .cpp -- the decomposition, combining-class and
// composition tables cover the whole BMP and every astral plane).
//
// SURFACE (all in the UTF-16 code-unit domain -- the unit count equals
// System.String.Length exactly, surrogate pairs occupy two units like .NET):
//
//   Normalize(NormalizationForm form)  -> a NEW string in the requested form
//   Normalize()                        -> the same, defaulting to NFC
//   IsNormalized(NormalizationForm)    -> true iff already in that form
//   IsNormalized()                     -> true iff already in NFC
//
// FORM VALUES -- the .NET Framework public enum System.Text.NormalizationForm
// (net48 oracle-verified 2026-10-24):
//     FormC  = 1
//     FormD  = 2
//     FormKC = 5
//     FormKD = 6
// A value outside that set throws System.ArgumentException (net48
// csc-probe-verified: "abc".Normalize((NormalizationForm)99) ->
// ArgumentException; the receiver is null-checked FIRST, so a null receiver
// throws NullReferenceException even for an invalid form).
//
// SEMANTIC BASELINE: .NET Framework 4.8, verified byte-for-byte against the
// net48 oracle. Normalize returns a fresh string in the requested form; an
// already-normalized string returns an equal string (content equality --
// .NET Framework does not special-case the already-normalized identity the way
// .NET Core's Span-based Normalize does, and the domain does not rely on
// reference identity here). IsNormalized normalizes and compares, so it is
// true exactly when the string is a fixed point of the requested form.
//
// GC SAFETY: the receiver payload is decoded into a non-GC std::vector BEFORE
// the single result allocation (il2cpp_string_new), so the receiver is never
// read after a GC point and no rooting is required. The result is allocated
// once and returned directly.
//------------------------------------------------------------------------------

#include "il2cpp_object.h"
#include "il2cpp_string.h"

#include <cstdint>

namespace il2cpp {
namespace runtime {

// Normalize(NormalizationForm form): a NEW string in the requested form.
// form is the raw System.Text.NormalizationForm value (FormC=1, FormD=2,
// FormKC=5, FormKD=6); anything else throws System.ArgumentException.
// A null receiver throws System.NullReferenceException (checked first).
Il2CppObject* icall_string_normalize(Il2CppObject* this_, int32_t form);

// IsNormalized(NormalizationForm form): true iff 'this_' is already in the
// requested form. Same form validation and null-check order as Normalize.
bool icall_string_is_normalized(Il2CppObject* this_, int32_t form);

} // namespace runtime
} // namespace il2cpp
